	<script>
		$('form').on('submit', function(e){
			var str = $(this).find('input[name="name"]').val(),
				flag = true;
			for(i = 0; i < str.length; i++){
				if ( str[i] != ' ') {
					flag = false;
				}
			}
			if ( flag ) {
				$(this).find('input[name="name"]').val('');
				
				e.preventDefault();
				return false;
			}
		})
	</script>
